import flatpickr from "flatpickr";
import "flatpickr/dist/flatpickr.min.css";

import iziToast from "izitoast";
import "izitoast/dist/css/iziToast.min.css";

const inputDate = document.querySelector('#datetime-picker');
const startBtn = document.querySelector('button[data-start]');

const timerSpans = {
  days: document.querySelector('[data-days]'),
  hours: document.querySelector('[data-hours]'),
  minutes: document.querySelector('[data-minutes]'),
  seconds: document.querySelector('[data-seconds]'),
};

startBtn.disabled = true;

let userSelectedDate = null;
let timerId = null;

const options = {
  enableTime: true,
  time_24hr: true,
  defaultDate: new Date(),
  minuteIncrement: 1,
  onClose(selectedDates) {
    const pickedDate = selectedDates[0];
    if (!pickedDate || pickedDate.getTime() <= Date.now()) {
      iziToast.error({ message: 'Please choose a date in the future' });
      startBtn.disabled = true;
    } else {
      userSelectedDate = pickedDate;
      startBtn.disabled = false;
    }
  },
};

flatpickr(inputDate, options);

startBtn.addEventListener('click', () => {
  startBtn.disabled = true;
  inputDate.disabled = true;

  function updateTimerInterface() {
    const currentTime = Date.now();
    const msLeft = userSelectedDate.getTime() - currentTime;

    if (msLeft <= 0) {
      clearInterval(timerId);
      inputDate.disabled = false;
      Object.values(timerSpans).forEach(span => span.textContent = '00');
      return;
    }

    const time = convertMs(msLeft);
    Object.keys(timerSpans).forEach(key => {
      timerSpans[key].textContent = addLeadingZero(time[key]);
    });
  }

  updateTimerInterface();
  timerId = setInterval(updateTimerInterface, 1000);
});

function convertMs(ms) {
  const second = 1000;
  const minute = second * 60;
  const hour = minute * 60;
  const day = hour * 24;

  const days = Math.floor(ms / day);
  const hours = Math.floor((ms % day) / hour);
  const minutes = Math.floor(((ms % day) % hour) / minute);
  const seconds = Math.floor((((ms % day) % hour) % minute) / second);

  return { days, hours, minutes, seconds };
}

function addLeadingZero(value) {
  return String(value).padStart(2, "0");
}
